import {WILLOW_SOURCE,willowStatus,willowWalk,startWillowWalk,spinWillow,stepWillow,willowText} from './willow-path-core.mjs';
import {hearButton,stopSpeech} from './play-media.mjs';

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let stepVoice=false,confirming=false,notice='';
export function resetWillowVoice(){stepVoice=false;confirming=false;notice='';stopSpeech();}
const tokenName=(text,token)=>text[token==='leaf'?'tokenLeaf':'tokenLantern'];
const phrase=(text,key,values)=>willowText(text[key],values);
const symbol=token=>token==='leaf'?'<svg viewBox="0 0 28 28" aria-hidden="true"><path d="M4 22C5 9 16 3 24 4c0 12-9 20-20 18Z" fill="#397958" stroke="#173f37" stroke-width="2"/><path d="M5 22 20 8" stroke="#fff9df" stroke-width="2"/></svg>':'<svg viewBox="0 0 28 28" aria-hidden="true"><path d="M7 11h14l-2 12H9Z" fill="#e9b84a" stroke="#173f37" stroke-width="2"/><path d="M9 11 12 5h4l3 6M13 2h2" fill="none" stroke="#173f37" stroke-width="2"/><circle cx="14" cy="17" r="3" fill="#fff9df"/></svg>';
const marker=(token,text)=>`<span class="willow-token willow-${token}" data-token="${token}" aria-label="${esc(tokenName(text,token))}">${symbol(token)}</span>`;
const modePicker=text=>`<fieldset class="willow-modes" data-willow-mode><legend>${esc(text.modeTip)}</legend><label><input type="radio" name="willow-mode" value="two" checked> ${esc(text.modeTwo)}</label><label><input type="radio" name="willow-mode" value="solo"> ${esc(text.modeSolo)}</label></fieldset>`;
const header=text=>`<header class="willow-heading"><a class="back" href="#numbers">← Number Garden</a><h1>${esc(text.title)}</h1><p>${esc(text.invitation)}</p></header>`;
function board(walk){const {source,positions,turn,spin,done}=walk,t=source.text,n=source.squares,active=tokenName(t,turn);
 const at=(token,p)=>p===n?null:p===0?phrase(t,'atGate',{token:tokenName(t,token)}):phrase(t,'atStone',{token:tokenName(t,token),square:p});
 const arrival=positions.leaf===n&&!done?t.leafArrives:positions.lantern===n&&!done?t.lanternArrives:'';
 const turnLine=done?t.ending:phrase(t,'turnLine',{token:active});
 const positionLine=done?'':[arrival,at('leaf',positions.leaf),at('lantern',positions.lantern)].filter(Boolean).join(' ');
 const status=done?t.ending:`${turnLine} ${positionLine} ${phrase(t,'stepButton',{square:positions[turn]+1})}`;
 const spinLine=spin?phrase(t,'spinResult',{token:active,value:spin.value}):'';
 const next=positions[turn]+1;
 const occupied=new Set([positions.leaf,positions.lantern]);
 return `${header(t)}<section class="willow-play" data-willow-root>${notice?`<p role="alert" tabindex="-1" data-willow-notice>${esc(notice)}</p>`:''}<p class="willow-mode-label">${esc(walk.mode==='two'?t.modeTwo:t.modeSolo)}</p><p class="willow-adult-tip">${esc(t.adultTip)}</p><div class="willow-legend"><span>${marker('leaf',t)} ${esc(t.tokenLeaf)}</span><span>${marker('lantern',t)} ${esc(t.tokenLantern)}</span></div><div class="willow-board" role="group" aria-label="${esc(t.title)}"><div class="willow-gate"><span>${esc(t.gateLabel)}</span><div class="willow-gate-tokens">${positions.leaf===0?marker('leaf',t):''}${positions.lantern===0?marker('lantern',t):''}</div></div><ol class="willow-track">${Array.from({length:n},(_,i)=>{const square=i+1;return `<li class="willow-stone" data-willow-stone="${square}" aria-label="Stone ${square}${positions.leaf===square?`, ${esc(t.tokenLeaf)}`:''}${positions.lantern===square?`, ${esc(t.tokenLantern)}`:''}"><span class="willow-numeral">${square}</span><span class="willow-stone-tokens">${positions.leaf===square?marker('leaf',t):''}${positions.lantern===square?marker('lantern',t):''}</span></li>`;}).join('')}</ol><span class="willow-bridge">${esc(t.bridgeLabel)}</span></div>${done?'':`<p class="willow-status" data-willow-status>${esc(status)}</p>`}<p class="willow-live" data-willow-live role="status" aria-live="polite"></p>${spin?`<p class="willow-spin-result">${esc(spinLine)} ${spin.value===1?esc(t.oneWord):esc(t.twoWord)} <span class="willow-dots" aria-hidden="true">${'●'.repeat(spin.value)}</span></p>`:''}<div class="willow-actions">${done?`<p id="willow-ending" data-willow-status tabindex="-1">${esc(t.ending)}</p>`:spin?`<button type="button" class="primary" data-willow-step>${esc(phrase(t,'stepButton',{square:next}))}</button>`:`<button type="button" class="primary" data-willow-spin>${esc(phrase(t,'spinButton',{token:active}))}</button>`}<button type="button" class="secondary" data-willow-voice aria-pressed="${stepVoice}">${esc(stepVoice?t.stepVoiceOn:t.stepVoiceOff)}</button></div><div class="willow-events">${source.events.filter(e=>occupied.has(e.square)).map(e=>`<details class="willow-event" data-willow-event="${e.square}"><summary>${esc(phrase(t,'eventButton',{square:e.square}))}</summary><h2>${esc(e.title)}</h2><p>${esc(e.body)}</p>${hearButton(e.body,phrase(t,'eventHearButton',{square:e.square}))}</details>`).join('')}</div><details class="willow-help"><summary>${esc(t.helpTitle)}</summary><p>${esc(t.helpBody)}</p>${hearButton(t.helpBody,t.helpTitle)}</details><div class="willow-new"><button type="button" class="secondary" data-willow-new>${esc(t.newButton)}</button>${confirming?`<div class="willow-confirm" role="group" aria-label="${esc(t.newButton)}"><p>${esc(t.replaceWarning)}</p>${modePicker(t)}<button type="button" class="secondary" data-willow-cancel>${esc(t.keepButton)}</button><button type="button" class="primary" data-willow-confirm>${esc(t.replaceButton)}</button></div>`:''}</div><a href="#numbers">Back to Number Garden</a></section>`;
}
export function willowPathPage(state){const status=willowStatus(state),walk=willowWalk(state);
 if(walk)return board(walk);
 if(status==='recovery')return `${header(WILLOW_SOURCE.text)}<section class="willow-recovery" data-willow-root>${notice?`<p role="alert" tabindex="-1" data-willow-notice>${esc(notice)}</p>`:''}<p data-willow-status>This saved walk cannot be opened here. Its original record is still in your notes. You can start a separate walk.</p><a href="#notes">Grown-up notes</a> <a href="#numbers">Back to Number Garden</a><button type="button" class="secondary" data-willow-new>Start a separate walk</button>${confirming?'<div class="willow-confirm" role="group" aria-label="Start a separate walk"><p>Start a separate walk? The earlier record stays in your notes.</p>'+modePicker(WILLOW_SOURCE.text)+'<button type="button" class="secondary" data-willow-cancel>Keep the earlier record</button><button type="button" class="primary" data-willow-confirm>Start a separate walk</button></div>':''}</section>`;
 const t=WILLOW_SOURCE.text;return `${header(t)}<section class="willow-intro" data-willow-root><p>${esc(t.adultTip)}</p>${modePicker(t)}<button type="button" class="primary" data-willow-start>${esc(t.startButton)}</button>${notice?`<p role="alert" tabindex="-1" data-willow-notice>${esc(notice)}</p>`:''}<details><summary>${esc(t.helpTitle)}</summary><p>${esc(t.helpBody)}</p>${hearButton(t.helpBody,t.helpTitle)}</details></section>`;
}
export function willowPathEntry(){const t=WILLOW_SOURCE.text;return `<section class="willow-entry"><h2>${esc(t.title)}</h2><p>${esc(t.invitation)}</p><a class="secondary" href="#numbers/path">${esc(t.bridgeLabel)}</a></section>`;}
export function bindWillowPath(state,{save,render,focus}={}){const scope=document.querySelector('[data-willow-root]');if(!scope)return;
 const mode=()=>scope.querySelector('input[name="willow-mode"]:checked')?.value||'two';
 const fresh=()=>{if(!startWillowWalk(state,mode())){notice='That new walk cannot start in this version. Any current walk stays as it is.';render?.();focus?.('[data-willow-notice]');return;}notice='';stepVoice=false;confirming=false;stopSpeech();save?.();render?.();focus?.('[data-willow-spin]');};
 scope.querySelector('[data-willow-start]')?.addEventListener('click',fresh);
 scope.querySelector('[data-willow-new]')?.addEventListener('click',()=>{confirming=true;render?.();focus?.('[data-willow-confirm]');});
 scope.querySelector('[data-willow-cancel]')?.addEventListener('click',()=>{confirming=false;render?.();focus?.('[data-willow-new]');});
 scope.querySelector('[data-willow-confirm]')?.addEventListener('click',fresh);
 scope.querySelector('[data-willow-voice]')?.addEventListener('click',()=>{stepVoice=!stepVoice;stopSpeech();render?.();focus?.('[data-willow-voice]');});
 scope.querySelector('[data-willow-spin]')?.addEventListener('click',()=>{const walk=willowWalk(state),name=tokenName(walk.source.text,walk.turn);if(!spinWillow(state))return;const value=walk.spin.value,spoken=phrase(walk.source.text,'spinResult',{token:name,value});save?.();render?.();focus?.('[data-willow-step]');announce(spoken);});
 scope.querySelector('[data-willow-step]')?.addEventListener('click',()=>{const walk=willowWalk(state),text=walk.source.text,result=stepWillow(state);if(!result)return;const next=tokenName(text,walk.turn),arrive=!result.done&&result.arrived?(result.token==='leaf'?text.leafArrives:text.lanternArrives):'';const turn=result.done?text.ending:result.passed?phrase(text,'turnLine',{token:next}):'';const spoken=`${tokenName(text,result.token)} ${result.square}. ${arrive} ${turn}`.trim();save?.();render?.();focus?.(result.done?'#willow-ending':result.passed?'[data-willow-spin]':'[data-willow-step]');announce(spoken);});
}
function announce(message){let spoken=false;if(stepVoice){const detail={text:message,language:'en',accepted:false};document.dispatchEvent(new CustomEvent('garden-speak-request',{detail}));spoken=detail.accepted;}if(!spoken){const live=document.querySelector('[data-willow-live]');if(live)live.textContent=message;}}
